CREATE TABLE IF NOT EXISTS users (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120), email VARCHAR(180) UNIQUE NOT NULL, phone VARCHAR(20), password_hash VARCHAR(255), email_verified BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS user_roles (user_id BIGINT NOT NULL, roles VARCHAR(40) NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS category (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(160) UNIQUE, slug VARCHAR(180), image_url VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS product (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(180), description TEXT, price DECIMAL(10,2), discount INT, stock INT, rating DOUBLE, reviews INT, image_url VARCHAR(500), best_seller BOOLEAN, newest BOOLEAN, category_id BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (category_id) REFERENCES category(id));
CREATE TABLE IF NOT EXISTS address (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, line1 VARCHAR(255), city VARCHAR(80), state VARCHAR(80), pin_code VARCHAR(10), phone VARCHAR(20), saved BOOLEAN, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, address_id BIGINT, status VARCHAR(40), subtotal DECIMAL(10,2), gst DECIMAL(10,2), shipping DECIMAL(10,2), grand_total DECIMAL(10,2), expected_delivery DATE, tracking_number VARCHAR(60) UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(address_id) REFERENCES address(id));
CREATE TABLE IF NOT EXISTS order_item (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT, product_id BIGINT, weight VARCHAR(20), quantity INT, price DECIMAL(10,2), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(product_id) REFERENCES product(id));
CREATE TABLE IF NOT EXISTS payment (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT UNIQUE, method VARCHAR(40), status VARCHAR(40), upi_id VARCHAR(120), screenshot_url VARCHAR(500), razorpay_payment_id VARCHAR(120), admin_note VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE IF NOT EXISTS review (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, product_id BIGINT, rating INT, comment TEXT, verified_purchase BOOLEAN, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES product(id));
CREATE TABLE IF NOT EXISTS wishlist (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, product_id BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id, product_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(product_id) REFERENCES product(id));
CREATE TABLE IF NOT EXISTS inventory (id BIGINT PRIMARY KEY AUTO_INCREMENT, product_id BIGINT UNIQUE, available_stock INT, alert_threshold INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(product_id) REFERENCES product(id));
CREATE TABLE IF NOT EXISTS coupon (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(40) UNIQUE, discount_percent INT, active BOOLEAN, expires_on DATE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS branch (id BIGINT PRIMARY KEY AUTO_INCREMENT, city VARCHAR(80), address VARCHAR(255), phone VARCHAR(20), open_hours VARCHAR(80), google_maps_link VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS faq (id BIGINT PRIMARY KEY AUTO_INCREMENT, question VARCHAR(255), answer TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS testimonial (id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_name VARCHAR(120), photo_url VARCHAR(500), rating INT, comment TEXT, verified_purchase BOOLEAN, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS video (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(180), youtube_id VARCHAR(40), thumbnail_url VARCHAR(500), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS notification (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT, title VARCHAR(160), message TEXT, `read` BOOLEAN DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, actor VARCHAR(180), action VARCHAR(120), entity_name VARCHAR(120), entity_id BIGINT, ip_address VARCHAR(80), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
